solution.solution.cpp:
#include <array>

template <typename T, std::size_t N>
T sumOf(const std::array<T, N>& values)
{
    T total{};
    for (const T& value : values)
    {
        total += value;
    }
    return total;
}

unitTests:
TEST("three ints") { CHECK_EQ(sumOf(std::array<int, 3>{ 1, 2, 3 }), 6); }
TEST("five ints") { CHECK_EQ(sumOf(std::array<int, 5>{ 10, 20, 30, 40, 50 }), 150); }
TEST("doubles") { CHECK_NEAR(sumOf(std::array<double, 2>{ 0.5, 0.25 }), 0.75, 1e-12); }

